const queryClient = new QueryClient();

type IconType = typeof Activity;
type Severity = 'CRITICAL' | 'HIGH' | 'MODERATE' | 'LOW';

const navGroups = [
  { label: 'Command', items: [{ href: '/', label: 'Overview', icon: Gauge }, { href: '/map', label: 'Map explorer', icon: MapIcon }, { href: '/incidents', label: 'Incidents', icon: Crosshair }] },
  { label: 'Intelligence', items: [{ href: '/persistent-sources', label: 'Persistent sources', icon: Radio }, { href: '/alerts', label: 'Alert queue', icon: Bell }, { href: '/analytics', label: 'Analytics', icon: BarChart3 }] },
  { label: 'Decision support', items: [{ href: '/copilot', label: 'AI copilot', icon: Bot }, { href: '/reports', label: 'Reports', icon: FileText }, { href: '/system', label: 'System health', icon: Activity }] },
];

const fmt = (value: unknown, fallback = '—') => value === undefined || value === null || value === '' ? fallback : String(value);
const timeAgo = (date?: string) => {
  if (!date) return 'Awaiting update';
  const mins = Math.max(1, Math.round((Date.now() - new Date(date).getTime()) / 60000));
  if (mins < 60) return `${mins}m ago`;
  if (mins < 1440) return `${Math.round(mins / 60)}h ago`;
  return `${Math.round(mins / 1440)}d ago`;
};

function severityClass(level?: string) {
  const value = String(level ?? '').toUpperCase();
  if (value === 'CRITICAL') return 'bg-[#8e2e27] text-[#fff7ec]';
  if (value === 'HIGH') return 'bg-[#d76a35] text-[#fff7ec]';
  if (value === 'MODERATE') return 'bg-[#e1aa47] text-[#332613]';
  return 'bg-[#5b9e91] text-[#f4fbf8]';
}

function StatusPill({ value, tone }: { value?: string; tone?: 'severity' | 'status' }) {
  const v = fmt(value, 'UNKNOWN').toUpperCase();
  const statusTone = tone === 'status' && v === 'RESOLVED' ? 'bg-[#d9e6d8] text-[#2c5f4b]' : tone === 'status' && v === 'INVESTIGATING' ? 'bg-[#d8e8e8] text-[#236b68]' : severityClass(v);
  return <span data-testid={`status-pill-${v.toLowerCase()}`} className={`inline-flex items-center gap-1 rounded-sm px-2 py-1 font-mono text-[10px] font-medium tracking-[.12em] ${statusTone}`}>{v}</span>;
}

function LoadingRows({ count = 3 }: { count?: number }) {
  return <div className="space-y-2" data-testid="loading-skeleton">{Array.from({ length: count }).map((_, i) => <div key={i} className="h-12 animate-pulse rounded-sm bg-foreground/5" />)}</div>;
}

function QueryState({ error, onRetry }: { error?: unknown; onRetry?: () => void }) {
  if (!error) return null;
  return <div className="border border-destructive/30 bg-destructive/5 p-5" data-testid="state-error"><div className="flex items-center gap-2 text-sm font-semibold text-destructive"><AlertTriangle size={16} /> Signal unavailable</div><p className="mt-2 text-xs text-muted-foreground">The latest feed could not be reached. Existing context remains available.</p>{onRetry && <button data-testid="button-retry" onClick={onRetry} className="mt-4 inline-flex items-center gap-2 border border-destructive/30 px-3 py-2 text-xs font-semibold text-destructive hover:bg-destructive/10"><RefreshCw size={13} /> Retry feed</button>}</div>;
}

function Header({ title, eyebrow, onMenu }: { title: string; eyebrow?: string; onMenu: () => void }) {
  const [query, setQuery] = useState('');
  const [location, setLocation] = useLocation();
  const search = useSearchIncidents({ q: query }, { query: { enabled: query.length > 1, queryKey: getSearchIncidentsQueryKey({ q: query }) } });
  return <header className="sticky top-0 z-30 flex min-h-[74px] items-center justify-between border-b border-border bg-background/95 px-4 backdrop-blur md:px-8">
    <div className="flex items-center gap-3"><button aria-label="Open navigation" data-testid="button-open-menu" onClick={onMenu} className="rounded-sm p-2 text-muted-foreground hover:bg-muted md:hidden"><Menu size={19} /></button><div><div className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">{eyebrow ?? 'Thermal intelligence'}</div><h1 className="mt-1 font-display text-xl font-bold tracking-[-.03em] md:text-2xl">{title}</h1></div></div>
    <div className="relative hidden w-[280px] md:block lg:w-[360px]">
      <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search incidents, places, IDs" data-testid="input-global-search" className="h-10 w-full border border-border bg-card pl-9 pr-3 text-xs outline-none ring-primary/30 placeholder:text-muted-foreground focus:ring-2" />
      {query.length > 1 && <div className="absolute top-12 z-20 w-full border border-border bg-card p-2 shadow-xl">{search.isLoading ? <div className="p-3 text-xs text-muted-foreground">Searching live index...</div> : search.data?.length ? search.data.slice(0, 5).map((item) => <button key={item.id} data-testid={`search-result-${item.id}`} onClick={() => { setLocation(`/incidents?selected=${item.id}`); setQuery(''); }} className="flex w-full items-start justify-between gap-3 p-3 text-left hover:bg-muted"><span><strong className="block text-xs">{item.title}</strong><small className="text-[11px] text-muted-foreground">{item.subtitle}</small></span><StatusPill value={item.riskLevel} tone="severity" /></button>) : <div className="p-3 text-xs text-muted-foreground">No matching incident records.</div>}</div>}
    </div>
    <div className="flex items-center gap-2 md:gap-4"><div className="hidden items-center gap-2 font-mono text-[10px] uppercase tracking-[.12em] text-muted-foreground sm:flex"><span className="h-2 w-2 rounded-full bg-accent shadow-[0_0_0_3px_hsl(var(--accent)/.16)]" /> Live feed</div><button data-testid="button-header-alerts" onClick={() => setLocation('/alerts')} className="relative rounded-sm p-2 text-muted-foreground hover:bg-muted"><Bell size={17} /><span className="absolute right-1 top-1 h-1.5 w-1.5 rounded-full bg-primary" /></button><div className="flex h-8 w-8 items-center justify-center rounded-sm bg-sidebar font-mono text-[10px] font-medium text-sidebar-primary">OP</div></div>
  </header>;
}

function Sidebar({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [location] = useLocation();
  return <><div className={`fixed inset-0 z-40 bg-sidebar/40 transition-opacity md:hidden ${open ? 'opacity-100' : 'pointer-events-none opacity-0'}`} onClick={onClose} /><aside className={`fixed inset-y-0 left-0 z-50 flex w-[244px] flex-col bg-sidebar text-sidebar-foreground transition-transform md:static md:z-auto md:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}>
    <div className="flex h-[74px] items-center justify-between border-b border-sidebar-border px-5"><Link href="/" data-testid="link-logo" className="flex items-center gap-3" onClick={onClose}><span className="relative flex h-8 w-8 items-center justify-center rounded-sm bg-sidebar-primary text-sidebar-primary-foreground"><Thermometer size={17} /><span className="absolute -right-1 -top-1 h-2 w-2 rounded-full bg-[#e5b34c]" /></span><span><strong className="block font-display text-[15px] tracking-[-.03em]">THERMOSCOPE</strong><small className="font-mono text-[9px] tracking-[.2em] text-sidebar-foreground/55">AI COMMAND CENTER</small></span></Link><button data-testid="button-close-menu" onClick={onClose} className="rounded-sm p-1 text-sidebar-foreground/50 hover:bg-sidebar-accent md:hidden"><X size={17} /></button></div>
    <div className="flex-1 overflow-y-auto px-3 py-6">{navGroups.map((group) => <div key={group.label} className="mb-7"><div className="px-3 pb-2 font-mono text-[9px] uppercase tracking-[.2em] text-sidebar-foreground/40">{group.label}</div>{group.items.map((item) => { const Icon = item.icon; const active = location === item.href || (item.href !== '/' && location.startsWith(item.href)); return <Link href={item.href} onClick={onClose} data-testid={`link-nav-${item.label.toLowerCase().replaceAll(' ', '-')}`} key={item.href} className={`group flex items-center gap-3 border-l-2 px-3 py-2.5 text-xs font-semibold transition-colors ${active ? 'border-sidebar-primary bg-sidebar-accent text-sidebar-foreground' : 'border-transparent text-sidebar-foreground/60 hover:bg-sidebar-accent/70 hover:text-sidebar-foreground'}`}><Icon size={16} className={active ? 'text-sidebar-primary' : 'text-sidebar-foreground/45'} />{item.label}{item.label === 'Alert queue' && <span className="ml-auto rounded-sm bg-[#b44837] px-1.5 py-0.5 font-mono text-[9px] text-white">04</span>}</Link> })}</div>)}</div>
    <div className="border-t border-sidebar-border p-4"><div className="mb-3 flex items-center justify-between font-mono text-[9px] uppercase tracking-[.16em] text-sidebar-foreground/45"><span>Orbit stack</span><span className="text-sidebar-primary">v0.8.4</span></div><div className="flex items-center gap-2 text-[11px] text-sidebar-foreground/70"><span className="h-1.5 w-1.5 rounded-full bg-sidebar-primary" /> Pipeline nominal <ChevronRight size={13} className="ml-auto opacity-40" /></div></div>
  </aside></>;
}

function Shell({ children, title, eyebrow }: { children: ReactNode; title: string; eyebrow?: string }) {
  const [menuOpen, setMenuOpen] = useState(false);
  return <div className="noise flex min-h-[100dvh] bg-background text-foreground"><Sidebar open={menuOpen} onClose={() => setMenuOpen(false)} /><main className="min-w-0 flex-1"><Header title={title} eyebrow={eyebrow} onMenu={() => setMenuOpen(true)} /><div className="app-grid min-h-[calc(100dvh-74px)] p-4 md:p-7 lg:p-8">{children}</div></main></div>;
}

function SectionHeading({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: ReactNode }) {
  return <div className="mb-5 flex items-end justify-between gap-4"><div>{eyebrow && <div className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">{eyebrow}</div>}<h2 className="mt-1 text-lg font-bold tracking-[-.025em]">{title}</h2></div>{action}</div>;
}

function Metric({ label, value, detail, icon: Icon, accent = 'primary' }: { label: string; value: ReactNode; detail: string; icon: IconType; accent?: 'primary' | 'accent' | 'destructive' }) {
  const tint = accent === 'accent' ? 'text-accent' : accent === 'destructive' ? 'text-destructive' : 'text-primary';
  return <div className="border border-border bg-card p-4 shadow-[0_1px_0_hsl(var(--foreground)/.03)]" data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><div className="font-mono text-[10px] uppercase tracking-[.13em] text-muted-foreground">{label}</div><Icon size={16} className={tint} /></div><div className="mt-3 font-display text-3xl font-bold tracking-[-.06em]">{value}</div><div className="mt-1 text-[11px] text-muted-foreground">{detail}</div></div>;
}

function DemoScenarioStrip({ onSelect }: { onSelect: (incidentId: string) => void }) {
  const scenarios = [
    { label: 'Industrial fire', detail: 'High heat · factory nearby', id: 'TH-001', tone: 'bg-[#8e2e27]' },
    { label: 'Persistent source', detail: '14 detections · 6 active days', id: 'TH-010', tone: 'bg-[#d76a35]' },
    { label: 'Agricultural burn', detail: 'Moderate heat · open land', id: 'TH-024', tone: 'bg-[#e1aa47]' },
    { label: 'Vegetation / wildfire', detail: 'Spread cluster · forest edge', id: 'TH-031', tone: 'bg-[#5b9e91]' },
    { label: 'Critical incident', detail: 'Highest priority review', id: 'TH-001', tone: 'bg-[#8e2e27]' },
  ];
  return <section className="mb-6 border border-border bg-card" data-testid="demo-scenario-strip"><div className="flex flex-col gap-2 border-b border-border px-4 py-3 sm:flex-row sm:items-center sm:justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[.18em] text-accent">Demo mode / curated scenarios</div><p className="mt-1 text-[11px] text-muted-foreground">Follow one signal through the full investigation pipeline.</p></div><span className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">Deterministic FIRMS dataset</span></div><div className="grid divide-y divide-border sm:grid-cols-5 sm:divide-x sm:divide-y-0">{scenarios.map((scenario) => <button key={`${scenario.label}-${scenario.id}`} data-testid={`button-demo-${scenario.label.toLowerCase().replaceAll(' ', '-')}`} onClick={() => onSelect(scenario.id)} className="group flex items-center gap-3 px-4 py-3 text-left transition-colors hover:bg-muted/60"><span className={`h-2.5 w-2.5 shrink-0 rounded-full ${scenario.tone} shadow-[0_0_0_4px_hsl(var(--background))]`} /><span className="min-w-0"><strong className="block truncate text-[11px]">{scenario.label}</strong><span className="mt-1 block truncate font-mono text-[9px] text-muted-foreground">{scenario.detail}</span></span><ChevronRight size={13} className="ml-auto shrink-0 text-muted-foreground/50 transition-transform group-hover:translate-x-0.5" /></button>)}</div></section>;
}

function MapCanvas({ incidents = [], observations = [], selectedId, onSelect, large = false }: { incidents?: any[]; observations?: any[]; selectedId?: string; onSelect?: (id: string) => void; large?: boolean }) {
  const points = (incidents.length ? incidents : observations).slice(0, 18);
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [layersOpen, setLayersOpen] = useState(false);
  const [showThermal, setShowThermal] = useState(true);
  const dragging = useRef<{ x: number; y: number; panX: number; panY: number } | null>(null);
  const handlePointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    if ((event.target as HTMLElement).closest('button')) return;
    dragging.current = { x: event.clientX, y: event.clientY, panX: pan.x, panY: pan.y };
    event.currentTarget.setPointerCapture(event.pointerId);
  };
  const handlePointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    if (!dragging.current) return;
    setPan({
      x: dragging.current.panX + (event.clientX - dragging.current.x) / 4,
      y: dragging.current.panY + (event.clientY - dragging.current.y) / 4,
    });
  };
  const stopDragging = () => { dragging.current = null; };
  return <div onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={stopDragging} onPointerCancel={stopDragging} onPointerLeave={stopDragging} className={`map-surface relative min-h-[340px] cursor-grab border border-[#afc2bf] active:cursor-grabbing ${large ? 'h-[calc(100dvh-195px)] min-h-[520px]' : 'h-[430px]'}`} data-testid="map-live-surface"><div className="absolute inset-0 z-[1] opacity-70" style={{ backgroundImage: 'linear-gradient(transparent 49.7%, rgba(25,72,75,.15) 50%, transparent 50.3%), linear-gradient(90deg, transparent 49.7%, rgba(25,72,75,.15) 50%, transparent 50.3%)', backgroundSize: '150px 150px' }} /><div className="absolute left-[12%] top-[22%] z-[1] h-20 w-40 rounded-[50%] border border-[#547b78]/25 rotate-[18deg]" /><div className="absolute left-[61%] top-[37%] z-[1] h-28 w-52 rounded-[50%] border border-[#547b78]/25 -rotate-[26deg]" /><div className="absolute inset-x-0 top-1/2 z-[2] h-px bg-[#355e60]/20 scan-line" /><div className="absolute left-4 top-4 z-[3] flex gap-2"><span className="bg-[#eef4f0]/90 px-2 py-1 font-mono text-[9px] uppercase tracking-[.13em] text-[#265855]">Live thermal layer</span><span className="bg-[#eef4f0]/90 px-2 py-1 font-mono text-[9px] text-[#265855]">± 1.0 km</span></div><div className="absolute right-4 top-4 z-[5] flex flex-col border border-[#527a76]/30 bg-[#eef4f0]/80 text-[#265855]"><button data-testid="button-map-zoom-in" onClick={() => setZoom((value) => Math.min(1.8, value + 0.15))} className="border-b border-[#527a76]/20 p-2 hover:bg-white/40">+</button><button data-testid="button-map-zoom-out" onClick={() => setZoom((value) => Math.max(.7, value - 0.15))} className="p-2 hover:bg-white/40">−</button></div><div className="absolute right-[3.25rem] top-4 z-[5]"><button data-testid="button-map-layers" onClick={() => setLayersOpen((open) => !open)} className="border border-[#527a76]/30 bg-[#eef4f0]/90 px-2 py-2 font-mono text-[9px] uppercase tracking-wider text-[#265855] hover:bg-white">Layers</button>{layersOpen && <div className="mt-1 w-36 border border-[#527a76]/30 bg-[#eef4f0]/95 p-2 text-[10px] text-[#265855] shadow-lg"><label className="flex items-center gap-2 p-1.5"><input type="checkbox" checked={showThermal} onChange={(event) => setShowThermal(event.target.checked)} /> Thermal anomalies</label><div className="mt-1 border-t border-[#527a76]/20 pt-2 font-mono text-[9px] uppercase tracking-wider text-[#527a76]">Context: OSM demo</div></div>}</div>{points.length && showThermal ? points.map((point: any, i: number) => { const x = 12 + ((Math.abs(Number(point.longitude ?? point.lon ?? i * 17)) * 3.2 + i * 7) % 76); const y = 22 + ((Math.abs(Number(point.latitude ?? point.lat ?? i * 11)) * 2.4 + i * 11) % 57); const level = point.riskLevel ?? (Number(point.riskScore) > 80 ? 'CRITICAL' : Number(point.riskScore) > 60 ? 'HIGH' : 'MODERATE'); return <button key={point.id ?? i} data-testid={`map-point-${point.id ?? i}`} onClick={() => onSelect?.(point.id)} className="group absolute z-[4] -translate-x-1/2 -translate-y-1/2" style={{ left: `${50 + (x - 50) * zoom + pan.x}%`, top: `${50 + (y - 50) * zoom + pan.y}%` }}><span className={`absolute -inset-3 rounded-full opacity-25 blur-[1px] ${level === 'CRITICAL' ? 'bg-[#8e2e27]' : level === 'HIGH' ? 'bg-[#d76a35]' : 'bg-[#e5a448]'}`} /><span className={`pulse-dot relative block h-3 w-3 rounded-full border-2 border-[#eff6ef] shadow-md ${level === 'CRITICAL' ? 'bg-[#8e2e27]' : level === 'HIGH' ? 'bg-[#d76a35]' : 'bg-[#e5a448]'}`} /><span className="pointer-events-none absolute bottom-4 left-1/2 hidden -translate-x-1/2 whitespace-nowrap border border-[#527a76]/30 bg-[#eef4f0] px-2 py-1 text-[10px] font-semibold text-[#265855] shadow-sm group-hover:block">{point.locationName ?? `${Number(point.latitude ?? 0).toFixed(2)}°, ${Number(point.longitude ?? 0).toFixed(2)}°`}</span></button> }) : <div className="absolute inset-0 z-[3] flex items-center justify-center"><div className="border border-[#527a76]/30 bg-[#eef4f0]/90 px-5 py-4 text-center text-xs text-[#265855]"><LocateFixed size={18} className="mx-auto mb-2" /><span>{points.length ? 'Thermal layer hidden' : 'No anomalies in current viewport'}</span></div></div>}<div className="absolute bottom-4 left-4 z-[3] flex items-center gap-4 bg-[#eef4f0]/90 px-3 py-2 font-mono text-[9px] uppercase tracking-[.1em] text-[#265855]"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#8e2e27]" /> Critical</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#d76a35]" /> High</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#e5a448]" /> Moderate</span></div><div className="absolute bottom-4 right-4 z-[3] bg-[#eef4f0]/90 px-2 py-1 font-mono text-[9px] text-[#265855]">SENTINEL GRID · 38°N 24°E</div></div>;
}

function IncidentRow({ incident, selected, onClick }: { incident: any; selected?: boolean; onClick?: () => void }) {
  return <button data-testid={`row-incident-${incident.id}`} onClick={onClick} className={`grid w-full grid-cols-[1fr_auto] gap-3 border-b border-border px-4 py-3 text-left transition-colors hover:bg-muted/60 ${selected ? 'border-l-2 border-l-primary bg-primary/5' : ''}`}><span className="min-w-0"><span className="flex items-center gap-2"><strong className="truncate text-xs">{fmt(incident.locationName, 'Unresolved location')}</strong><StatusPill value={incident.riskLevel} tone="severity" /></span><span className="mt-1 block font-mono text-[10px] text-muted-foreground">{fmt(incident.classificationLabel, incident.classification)} · {timeAgo(incident.timestamp)}</span></span><span className="text-right"><strong className="block font-mono text-sm">{fmt(incident.riskScore)}</strong><small className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">risk</small></span></button>;
}

function Dashboard() {
  const summaryQuery = useGetDashboardSummary();
  const [, setLocation] = useLocation();
  const firesQuery = useGetFires(undefined, { query: { staleTime: 60000, queryKey: getGetFiresQueryKey() } });
  const summary: any = summaryQuery.data;
  const incidents = summary?.incidents ?? [];
  const observations = firesQuery.data ?? [];
  return <Shell title="Overview" eyebrow="Command / live brief"><div className="reveal"><div className="mb-6 flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div><p className="max-w-xl text-sm leading-6 text-muted-foreground">A clean chain from orbital signal to operational decision. Watch the thermal picture, then open the context that changes the call.</p></div><div className="flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.14em] text-muted-foreground"><span className="h-2 w-2 rounded-full bg-accent" /> Last sync {timeAgo(summary?.lastUpdate)}</div></div><DemoScenarioStrip onSelect={(id) => setLocation(`/incidents?selected=${id}`)} /><QueryState error={summaryQuery.error} onRetry={() => summaryQuery.refetch()} /><div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">{summaryQuery.isLoading ? <div className="col-span-4"><LoadingRows count={1} /></div> : <><Metric label="Active anomalies" value={fmt(summary?.activeAnomalies)} detail="across current observation window" icon={Flame} /><Metric label="Likely industrial" value={fmt(summary?.likelyIndustrialFires)} detail="classification confidence ≥ nominal" icon={Database} accent="accent" /><Metric label="Critical incidents" value={fmt(summary?.criticalIncidents)} detail={`${fmt(summary?.highIncidents, '0')} high risk requiring review`} icon={ShieldAlert} accent="destructive" /><Metric label="Average risk score" value={summary?.avgRiskScore ? Number(summary.avgRiskScore).toFixed(1) : '—'} detail={`${fmt(summary?.newAlerts, '0')} new alerts in queue`} icon={Target} /></>}</div><div className="grid gap-6 xl:grid-cols-[1.45fr_.8fr]"><section className="min-w-0"><SectionHeading eyebrow="Geospatial picture" title="Live anomaly field" action={<Link href="/map" data-testid="link-open-map" className="inline-flex items-center gap-1.5 border border-border bg-card px-3 py-2 text-[11px] font-semibold hover:bg-muted">Open explorer <ChevronRight size={14} /></Link>} /><MapCanvas incidents={incidents} observations={observations} onSelect={(id) => setLocation(`/incidents?selected=${id}`)} /></section><section className="border border-border bg-card"><div className="flex items-center justify-between border-b border-border px-4 py-4"><div><div className="font-mono text-[10px] uppercase tracking-[.18em] text-accent">Priority queue</div><h2 className="mt-1 text-sm font-bold">Recent incidents</h2></div><Link href="/incidents" data-testid="link-view-incidents" className="text-[11px] font-semibold text-accent hover:underline">View all</Link></div><div>{summaryQuery.isLoading ? <div className="p-4"><LoadingRows /></div> : incidents.length ? incidents.slice(0, 6).map((incident: any) => <IncidentRow key={incident.id} incident={incident} onClick={() => setLocation(`/incidents?selected=${incident.id}`)} />) : <EmptyState title="No recent incidents" detail="The command picture is clear for this window." icon={Check} />}</div></section></div></div></Shell>;
}

function MapPage() {
  const [confidence, setConfidence] = useState('all');
  const [dayNight, setDayNight] = useState('all');
  const [satellite, setSatellite] = useState('all');
  const params: any = { confidence: confidence === 'all' ? undefined : confidence, dayNight: dayNight === 'all' ? undefined : dayNight, satellite: satellite === 'all' ? undefined : satellite };
  const fires = useGetFires(params);
  const incidents = useGetIncidents();
  return <Shell title="Map explorer" eyebrow="Command / geospatial"><div className="reveal"><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-muted-foreground">Inspect orbital detections by confidence, platform, and daylight condition. Drag to pan, or use the map controls to change the view.</p><div className="flex items-center gap-2"><button data-testid="button-refresh-map" onClick={() => { fires.refetch(); incidents.refetch(); }} className="inline-flex items-center gap-2 border border-border bg-card px-3 py-2 text-[11px] font-semibold hover:bg-muted"><RefreshCw size={14} /> Refresh</button><span className="inline-flex items-center gap-2 border border-border bg-card px-3 py-2 text-[11px] text-muted-foreground"><Layers3 size={14} /> OSM context · demo</span></div></div><div className="mb-4 flex flex-wrap gap-2 border-y border-border py-3"><FilterSelect label="Confidence" value={confidence} onChange={setConfidence} options={['all', 'low', 'nominal', 'high']} /><FilterSelect label="Day / night" value={dayNight} onChange={setDayNight} options={['all', 'D', 'N']} /><FilterSelect label="Satellite" value={satellite} onChange={setSatellite} options={['all', 'NOAA-20', 'NOAA-21', 'Suomi NPP']} /><span className="ml-auto hidden items-center gap-1 font-mono text-[10px] uppercase tracking-wider text-muted-foreground sm:flex"><span className="h-1.5 w-1.5 rounded-full bg-accent" /> {fires.data?.length ?? 0} observations</span></div><QueryState error={fires.error} onRetry={() => fires.refetch()} /><MapCanvas observations={fires.data ?? []} incidents={incidents.data ?? []} large /></div></Shell>;
}

function FilterSelect({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: string[] }) {
  return <label className="flex items-center gap-2 border border-border bg-card px-3 py-2 text-[10px] font-mono uppercase tracking-[.08em] text-muted-foreground"><span>{label}</span><select data-testid={`select-filter-${label.toLowerCase().replaceAll(' ', '-')}`} value={value} onChange={(e) => onChange(e.target.value)} className="bg-transparent font-sans text-xs font-semibold normal-case tracking-normal text-foreground outline-none">{options.map((option) => <option value={option} key={option}>{option === 'all' ? 'All' : option}</option>)}</select></label>;
}

function EmptyState({ title, detail, icon: Icon = CircleDot }: { title: string; detail: string; icon?: IconType }) {
  return <div className="flex flex-col items-center justify-center px-6 py-12 text-center" data-testid="empty-state"><Icon size={22} className="mb-3 text-accent" /><strong className="text-sm">{title}</strong><p className="mt-1 max-w-xs text-xs leading-5 text-muted-foreground">{detail}</p></div>;
}

function IncidentsPage() {
  const params = new URLSearchParams(window.location.search);
  const initial = params.get('selected');
  const [selectedId, setSelectedId] = useState<string | undefined>(initial ?? undefined);
  const [risk, setRisk] = useState('all');
  const [classification, setClassification] = useState('all');
  const incidents = useGetIncidents({ riskLevel: risk === 'all' ? undefined : risk as any, classification: classification === 'all' ? undefined : classification });
  const detail = useGetIncident(selectedId ?? '', { query: { enabled: !!selectedId, queryKey: getGetIncidentQueryKey(selectedId ?? '') } });
  const context = useGetIncidentContext(selectedId ?? '', { query: { enabled: !!selectedId, queryKey: getGetIncidentContextQueryKey(selectedId ?? '') } });
  const history = useGetIncidentHistory(selectedId ?? '', { query: { enabled: !!selectedId, queryKey: getGetIncidentHistoryQueryKey(selectedId ?? '') } });
  const fire = useGetFire(detail.data?.observationId ?? '', { query: { enabled: !!detail.data?.observationId, queryKey: getGetFireQueryKey(detail.data?.observationId ?? '') } });
  const rows = incidents.data ?? [];
  useEffect(() => { if (!selectedId && rows[0]?.id) setSelectedId(rows[0].id); }, [rows, selectedId]);
  return <Shell title="Incidents" eyebrow="Command / investigation"><div className="reveal"><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-muted-foreground">Move from a thermal signal to a defensible risk assessment.</p><div className="flex gap-2"><FilterSelect label="Risk" value={risk} onChange={setRisk} options={['all', 'CRITICAL', 'HIGH', 'MODERATE', 'LOW']} /><FilterSelect label="Class" value={classification} onChange={setClassification} options={['all', 'industrial', 'wildfire', 'agricultural']} /></div></div><QueryState error={incidents.error} onRetry={() => incidents.refetch()} /><div className="grid overflow-hidden border border-border bg-card lg:grid-cols-[330px_1fr]"><div className="border-b border-border lg:border-b-0 lg:border-r">{incidents.isLoading ? <div className="p-4"><LoadingRows count={6} /></div> : rows.length ? rows.map((item: any) => <IncidentRow key={item.id} incident={item} selected={item.id === selectedId} onClick={() => setSelectedId(item.id)} />) : <EmptyState title="No matching incidents" detail="Try widening the risk or classification filters." />}</div><IncidentDetail detail={detail.data} context={context.data} history={history.data} fire={fire.data} loading={detail.isLoading} /></div></div></Shell>;
}

function IncidentDetail({ detail, context, history, fire, loading }: { detail: any; context?: any[]; history?: any[]; fire?: any; loading?: boolean }) {
  if (loading) return <div className="p-6"><LoadingRows count={5} /></div>;
  if (!detail) return <EmptyState title="Select an incident" detail="Choose a record to open the full signal chain." icon={Crosshair} />;
  return <article data-testid={`incident-detail-${detail.id}`} className="min-w-0"><div className="flex flex-wrap items-start justify-between gap-4 border-b border-border p-5 md:p-6"><div><div className="flex flex-wrap items-center gap-2"><StatusPill value={detail.riskLevel} tone="severity" /><StatusPill value={detail.status} tone="status" /></div><h2 className="mt-3 text-2xl font-bold tracking-[-.04em]">{fmt(detail.locationName, 'Unnamed field')}</h2><p className="mt-1 font-mono text-[10px] text-muted-foreground">{detail.id} · {Number(detail.latitude).toFixed(3)}° N, {Number(detail.longitude).toFixed(3)}° E</p></div><div className="text-right"><div className="font-mono text-[10px] uppercase tracking-[.14em] text-muted-foreground">Risk score</div><div className="mt-1 font-display text-4xl font-bold text-primary">{fmt(detail.riskScore)}</div></div></div><div className="grid gap-5 p-5 md:grid-cols-2 md:p-6"><div><SectionHeading eyebrow="AI assessment" title="Why this matters" /><p className="text-sm leading-6 text-muted-foreground">{fmt(detail.explanation, 'No narrative is available for this incident yet.')}</p><div className="mt-5 space-y-2">{(detail.contributions ?? []).slice(0, 4).map((item: any, i: number) => <div key={i} className="flex gap-3 border-l-2 border-accent/50 bg-muted/40 p-3"><span className={`mt-1 h-2 w-2 shrink-0 rounded-full ${item.positive ? 'bg-accent' : 'bg-muted-foreground'}`} /><div><strong className="block text-xs">{item.label}</strong><span className="text-[11px] leading-5 text-muted-foreground">{item.detail}</span></div></div>)}</div></div><div><SectionHeading eyebrow="Evidence" title="Signal profile" /><div className="grid grid-cols-2 gap-2">{[['Brightness', fire?.brightness ?? detail.observation?.brightness, 'K'], ['FRP', fire?.frp ?? detail.observation?.frp, 'MW'], ['Confidence', fire?.confidence ?? detail.observation?.confidence, ''], ['Platform', fire?.satellite ?? detail.observation?.satellite, '']].map(([label, value, unit]) => <div key={String(label)} className="border border-border bg-background p-3"><div className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="mt-2 font-display text-lg font-bold">{fmt(value)}<small className="ml-1 font-mono text-[9px] font-normal text-muted-foreground">{unit}</small></div></div>)}</div><div className="mt-4 border border-border p-4"><div className="mb-4 flex items-center justify-between"><span className="font-mono text-[10px] uppercase tracking-[.13em] text-muted-foreground">Risk breakdown</span><span className="text-xs font-bold text-primary">{fmt(detail.breakdown?.final)}</span></div>{detail.breakdown && Object.entries(detail.breakdown).filter(([key]) => key !== 'final').slice(0, 6).map(([key, value]: any) => <div key={key} className="mb-2 flex items-center gap-3 text-[10px]"><span className="w-28 truncate text-muted-foreground">{key.replaceAll('_', ' ')}</span><span className="h-1.5 flex-1 bg-muted"><span className="block h-full bg-primary" style={{ width: `${Math.min(100, Number(value))}%` }} /></span><strong className="w-7 text-right font-mono">{value}</strong></div>)}</div></div></div><div className="grid gap-5 border-t border-border p-5 md:grid-cols-2 md:p-6"><div><SectionHeading eyebrow="Nearby context" title="What surrounds the signal" />{context?.length ? <div className="space-y-2">{context.map((item: any, i: number) => <div key={i} className="flex items-center justify-between border-b border-border py-2 text-xs"><span><strong>{item.featureName}</strong><small className="ml-2 text-muted-foreground">{item.featureType}</small></span><span className="font-mono text-muted-foreground">{item.distanceKm} km</span></div>)}</div> : <p className="text-xs text-muted-foreground">Context layer is still resolving.</p>}</div><div><SectionHeading eyebrow="Detection history" title="Signal over time" />{history?.length ? <div className="flex h-24 items-end gap-1 border-b border-border pb-1">{history.slice(-18).map((item: any, i: number) => <div key={i} title={`${item.brightness} K`} className="flex-1 bg-accent/70 hover:bg-accent" style={{ height: `${Math.max(8, Math.min(100, Number(item.brightness) || 15))}%` }} />)}</div> : <p className="text-xs text-muted-foreground">No historical detections attached.</p>}<div className="mt-3 flex justify-between font-mono text-[9px] text-muted-foreground"><span>First pass</span><span>Latest pass · {fmt(detail.modelVersion)}</span></div></div></div></article>;
}

function PersistentPage() {
  const sources = useGetPersistentSources();
  const [selected, setSelected] = useState<any>(null);
  return <Shell title="Persistent sources" eyebrow="Intelligence / recurrence"><div className="reveal"><div className="mb-5 flex items-center justify-between"><p className="text-sm text-muted-foreground">Places that keep glowing deserve a different question than places that flare once.</p><button data-testid="button-refresh-sources" onClick={() => sources.refetch()} className="inline-flex items-center gap-2 border border-border bg-card px-3 py-2 text-[11px] font-semibold hover:bg-muted"><RefreshCw size={14} /> Refresh</button></div><QueryState error={sources.error} onRetry={() => sources.refetch()} /><div className="grid gap-6 xl:grid-cols-[1fr_310px]"><div className="overflow-x-auto border border-border bg-card"><table className="w-full min-w-[720px] text-left"><thead className="border-b border-border bg-muted/50 font-mono text-[9px] uppercase tracking-[.12em] text-muted-foreground"><tr><th className="px-4 py-3">Source</th><th className="px-4 py-3">Detections</th><th className="px-4 py-3">Active days</th><th className="px-4 py-3">Mean / max K</th><th className="px-4 py-3">Persistence</th><th className="px-4 py-3">Risk</th></tr></thead><tbody>{sources.isLoading ? <tr><td colSpan={6} className="p-4"><LoadingRows count={5} /></td></tr> : (sources.data ?? []).map((item: any) => <tr key={item.id} data-testid={`row-source-${item.id}`} onClick={() => setSelected(item)} className="cursor-pointer border-b border-border text-xs hover:bg-muted/60"><td className="px-4 py-4"><strong>{item.locationName}</strong><span className="mt-1 block font-mono text-[10px] text-muted-foreground">{Number(item.latitude).toFixed(2)}°, {Number(item.longitude).toFixed(2)}° · {item.classificationLabel}</span></td><td className="px-4 py-4 font-mono">{item.detectionCount}</td><td className="px-4 py-4 font-mono">{item.activeDays}</td><td className="px-4 py-4 font-mono">{item.averageBrightness} / {item.maximumBrightness}</td><td className="px-4 py-4"><div className="flex items-center gap-2"><span className="h-1.5 w-16 bg-muted"><span className="block h-full bg-accent" style={{ width: `${item.persistenceScore}%` }} /></span>{item.persistenceScore}</div></td><td className="px-4 py-4"><StatusPill value={item.riskScore > 80 ? 'CRITICAL' : item.riskScore > 60 ? 'HIGH' : 'MODERATE'} tone="severity" /></td></tr>)}</tbody></table>{!sources.isLoading && !sources.data?.length && <EmptyState title="No persistent sources" detail="Recurrence will appear here as the observation history grows." icon={Radio} />}</div>{selected ? <div className="border border-border bg-sidebar p-5 text-sidebar-foreground"><div className="flex items-start justify-between"><div><div className="font-mono text-[9px] uppercase tracking-[.16em] text-sidebar-primary">Source drill-in</div><h2 className="mt-2 text-lg font-bold">{selected.locationName}</h2></div><button data-testid="button-close-source" onClick={() => setSelected(null)} className="text-sidebar-foreground/50 hover:text-sidebar-foreground"><X size={16} /></button></div><div className="mt-6 space-y-4">{[['First detected', selected.firstDetected], ['Last detected', selected.lastDetected], ['Classification', selected.classificationLabel], ['Risk score', selected.riskScore]].map(([label, value]) => <div key={String(label)} className="border-b border-sidebar-border pb-3"><span className="block font-mono text-[9px] uppercase tracking-wider text-sidebar-foreground/45">{label}</span><strong className="mt-1 block text-sm">{fmt(value)}</strong></div>)}</div><Link href={`/incidents`} data-testid="link-source-incidents" className="mt-6 flex items-center justify-between border border-sidebar-border px-3 py-3 text-xs font-semibold hover:bg-sidebar-accent">View related incidents <ChevronRight size={14} /></Link></div> : <div className="flex min-h-[260px] flex-col items-center justify-center border border-dashed border-border p-6 text-center text-muted-foreground"><Radio size={24} className="mb-3 text-accent" /><span className="text-sm font-semibold">Select a source</span><small className="mt-1 text-xs">Open a row to inspect recurrence.</small></div>}</div></div></Shell>;
}

function AlertsPage() {
  const alerts = useGetAlerts();
  const update = useUpdateAlertStatus();
  const [filter, setFilter] = useState('ALL');
  const items = (alerts.data ?? []).filter((a: any) => filter === 'ALL' || a.status === filter);
  const changeStatus = (id: string, status: any) => update.mutate({ id, data: { status } }, { onSuccess: () => alerts.refetch() });
  return <Shell title="Alert queue" eyebrow="Intelligence / response"><div className="reveal"><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-muted-foreground">Triage the alerts that need a human decision.</p><div className="flex gap-1">{['ALL', 'NEW', 'INVESTIGATING', 'ACKNOWLEDGED', 'RESOLVED'].map((item) => <button key={item} data-testid={`button-alert-filter-${item.toLowerCase()}`} onClick={() => setFilter(item)} className={`px-3 py-2 font-mono text-[9px] uppercase tracking-wider ${filter === item ? 'bg-sidebar text-sidebar-foreground' : 'border border-border bg-card text-muted-foreground hover:bg-muted'}`}>{item}</button>)}</div></div><QueryState error={alerts.error} onRetry={() => alerts.refetch()} /><div className="space-y-2">{alerts.isLoading ? <LoadingRows count={5} /> : items.length ? items.map((alert: any) => <div key={alert.id} data-testid={`card-alert-${alert.id}`} className="border border-border bg-card p-4"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-start"><div className="flex gap-3"><div className={`mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-sm ${severityClass(alert.severity)}`}><AlertTriangle size={15} /></div><div><div className="flex flex-wrap items-center gap-2"><h2 className="text-sm font-bold">{alert.title}</h2><StatusPill value={alert.severity} tone="severity" /></div><p className="mt-1 max-w-2xl text-xs leading-5 text-muted-foreground">{alert.message}</p><div className="mt-3 flex flex-wrap gap-3 font-mono text-[9px] uppercase tracking-wider text-muted-foreground"><span>{alert.locationName}</span><span>risk {alert.riskScore}</span><span>{timeAgo(alert.createdAt)}</span></div></div></div><div className="flex shrink-0 items-center gap-2 md:flex-col md:items-end"><StatusPill value={alert.status} tone="status" /><div className="flex gap-1">{alert.status !== 'INVESTIGATING' && alert.status !== 'RESOLVED' && <button data-testid={`button-investigate-${alert.id}`} disabled={update.isPending} onClick={() => changeStatus(alert.id, 'INVESTIGATING')} className="border border-border px-2 py-1.5 text-[10px] font-semibold hover:bg-muted">Investigate</button>}{alert.status !== 'ACKNOWLEDGED' && alert.status !== 'RESOLVED' && <button data-testid={`button-acknowledge-${alert.id}`} disabled={update.isPending} onClick={() => changeStatus(alert.id, 'ACKNOWLEDGED')} className="border border-border px-2 py-1.5 text-[10px] font-semibold hover:bg-muted">Acknowledge</button>}{alert.status !== 'RESOLVED' && <button data-testid={`button-resolve-${alert.id}`} disabled={update.isPending} onClick={() => changeStatus(alert.id, 'RESOLVED')} className="bg-sidebar px-2 py-1.5 text-[10px] font-semibold text-sidebar-foreground hover:bg-sidebar-accent">Resolve</button>}</div></div></div></div>) : <div className="border border-border bg-card"><EmptyState title="Queue is clear" detail="No alerts match this status filter." icon={Check} /></div>}</div></div></Shell>;
}

function AnalyticsPage() {
  const [range, setRange] = useState('7d');
  const analytics = useGetAnalytics({ range: range as any });
  const data: any = analytics.data;
  const max = Math.max(...(data?.trend ?? []).map((item: any) => item.anomalies), 1);
  return <Shell title="Analytics" eyebrow="Intelligence / patterns"><div className="reveal"><div className="mb-5 flex items-center justify-between"><p className="text-sm text-muted-foreground">Find the shape of the signal before it becomes an incident.</p><div className="flex gap-1">{['24h', '7d', '30d'].map((item) => <button key={item} data-testid={`button-range-${item}`} onClick={() => setRange(item)} className={`px-3 py-2 font-mono text-[10px] uppercase ${range === item ? 'bg-primary text-primary-foreground' : 'border border-border bg-card text-muted-foreground'}`}>{item}</button>)}</div></div><QueryState error={analytics.error} onRetry={() => analytics.refetch()} /><div className="grid gap-6 lg:grid-cols-[1.4fr_.8fr]"><div className="border border-border bg-card p-5"><SectionHeading eyebrow={`Rolling ${range}`} title="Anomalies over time" /><div className="flex h-56 items-end gap-2 border-b border-l border-border px-3 pb-0 pt-5">{(data?.trend ?? []).map((item: any, i: number) => <div key={i} className="group flex h-full flex-1 items-end gap-0.5"><div title={`${item.anomalies} anomalies`} className="relative w-full bg-primary/80 transition-colors group-hover:bg-primary" style={{ height: `${Math.max(5, item.anomalies / max * 100)}%` }} /><div title={`${item.industrial} industrial`} className="relative hidden w-1/2 bg-accent/80 sm:block" style={{ height: `${Math.max(5, item.industrial / max * 100)}%` }} /></div>)}</div><div className="mt-4 flex gap-4 font-mono text-[9px] uppercase tracking-wider text-muted-foreground"><span className="flex items-center gap-1.5"><i className="h-2 w-2 bg-primary" /> All anomalies</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 bg-accent" /> Industrial</span></div></div><div className="space-y-6"><Distribution title="Risk distribution" items={data?.riskDistribution} colors={['#8e2e27', '#d76a35', '#e1aa47', '#5b9e91']} /><Distribution title="Day / night" items={data?.dayNight} colors={['#2c6b73', '#d76a35']} /></div></div><div className="mt-6 border border-border bg-card p-5"><SectionHeading eyebrow="Platform mix" title="Observations by satellite" /><div className="grid gap-3 sm:grid-cols-3">{(data?.satellite ?? []).map((item: any, i: number) => <div key={i} className="flex items-center gap-3 border border-border p-4"><Satellite size={18} className="text-accent" /><div><strong className="block text-sm">{item.name}</strong><span className="font-mono text-xs text-muted-foreground">{item.value} observations</span></div></div>)}</div></div></div></Shell>;
}

function Distribution({ title, items, colors }: { title: string; items?: any[]; colors: string[] }) {
  const total = (items ?? []).reduce((sum, item) => sum + Number(item.value), 0) || 1;
  return <div className="border border-border bg-card p-5"><SectionHeading title={title} /><div className="space-y-3">{(items ?? []).map((item, i) => <div key={i}><div className="mb-1 flex justify-between text-xs"><span>{item.name}</span><strong className="font-mono">{item.value}</strong></div><div className="h-2 bg-muted"><div className="h-full" style={{ width: `${Number(item.value) / total * 100}%`, background: colors[i % colors.length] }} /></div></div>)}</div></div>;
}

function CopilotPage() {
  const [question, setQuestion] = useState('');
  const [answer, setAnswer] = useState<any>(null);
  const [incidentId, setIncidentId] = useState('');
  const incidents = useGetIncidents();
  const copilot = useAskCopilot();
  const ask = () => { if (!question.trim()) return; copilot.mutate({ data: { question, incidentId: incidentId || null } }, { onSuccess: (response) => { setAnswer(response); setQuestion(''); } }); };
  const prompts = ['Which incidents have the strongest industrial evidence?', 'What changed in the last 24 hours?', 'Explain the highest-risk persistent source.'];
  return <Shell title="AI copilot" eyebrow="Decision support / grounded"><div className="mx-auto max-w-5xl reveal"><div className="mb-7 max-w-2xl"><div className="mb-3 flex h-10 w-10 items-center justify-center rounded-sm bg-primary text-primary-foreground"><Sparkles size={19} /></div><h2 className="text-3xl font-bold tracking-[-.055em]">Ask the picture<br /><span className="text-accent">not the model.</span></h2><p className="mt-3 text-sm leading-6 text-muted-foreground">Thermoscope Copilot answers from the current anomaly, incident, and context layers. Every response returns the evidence used.</p></div><div className="grid gap-5 lg:grid-cols-[1.1fr_.75fr]"><div className="border border-border bg-card p-5"><div className="mb-4 flex items-center justify-between"><span className="font-mono text-[10px] uppercase tracking-[.16em] text-accent">Current session</span><span className="font-mono text-[10px] text-muted-foreground">{copilot.isPending ? 'Reasoning...' : 'Ready'}</span></div>{answer ? <div className="reveal"><div className="border-l-2 border-primary bg-primary/5 p-4 text-sm leading-6">{answer.answer}</div><div className="mt-5"><div className="mb-2 font-mono text-[10px] uppercase tracking-[.14em] text-muted-foreground">Evidence trail</div><div className="space-y-2">{(answer.evidence ?? []).map((item: string, i: number) => <div key={i} className="flex gap-2 text-xs text-muted-foreground"><Check size={14} className="mt-0.5 shrink-0 text-accent" />{item}</div>)}</div></div><button data-testid="button-new-question" onClick={() => setAnswer(null)} className="mt-5 border border-border px-3 py-2 text-xs font-semibold hover:bg-muted">Ask another question</button></div> : <div className="flex min-h-[230px] flex-col justify-end"><div className="mb-5 flex flex-wrap gap-2">{prompts.map((prompt) => <button key={prompt} data-testid={`button-prompt-${prompts.indexOf(prompt)}`} onClick={() => setQuestion(prompt)} className="border border-border bg-background px-3 py-2 text-left text-xs leading-4 hover:border-accent hover:bg-accent/5">{prompt}</button>)}</div><textarea data-testid="input-copilot-question" value={question} onChange={(e) => setQuestion(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) ask(); }} placeholder="Ask about the current thermal picture..." className="min-h-24 w-full resize-none border border-border bg-background p-3 text-sm outline-none focus:border-primary" /><div className="mt-3 flex flex-wrap items-center justify-between gap-3"><select data-testid="select-copilot-incident" value={incidentId} onChange={(e) => setIncidentId(e.target.value)} className="border border-border bg-background px-3 py-2 text-xs outline-none"><option value="">All incidents</option>{(incidents.data ?? []).map((item: any) => <option key={item.id} value={item.id}>{item.locationName} · {item.id}</option>)}</select><button data-testid="button-ask-copilot" onClick={ask} disabled={copilot.isPending || !question.trim()} className="inline-flex items-center gap-2 bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground disabled:cursor-not-allowed disabled:opacity-50">{copilot.isPending ? 'Analyzing' : 'Ask Copilot'} <Send size={14} /></button></div></div>}</div><div className="border border-sidebar-border bg-sidebar p-5 text-sidebar-foreground"><div className="flex items-center gap-2 text-sidebar-primary"><Bot size={18} /><span className="font-mono text-[10px] uppercase tracking-[.16em]">Grounding contract</span></div><h3 className="mt-5 text-lg font-bold tracking-[-.03em]">Signal. Context. Decision.</h3><div className="mt-5 space-y-4">{['No invented coordinates or incidents.', 'Evidence is returned with every answer.', 'Scope can be narrowed to one incident.'].map((item, i) => <div key={item} className="flex gap-3 border-t border-sidebar-border pt-3 text-xs text-sidebar-foreground/70"><span className="font-mono text-sidebar-primary">0{i + 1}</span>{item}</div>)}</div></div></div></div></Shell>;
}

function ReportsPage() {
  const incidents = useGetIncidents();
  const [incidentId, setIncidentId] = useState('');
  const report = useGenerateReport();
  const generated: any = report.data;
  const createReport = () => { if (incidentId) report.mutate({ data: { incidentId } }); };
  return <Shell title="Reports" eyebrow="Decision support / export"><div className="mx-auto max-w-5xl reveal"><div className="mb-6 flex items-end justify-between gap-4"><div><p className="text-sm text-muted-foreground">Turn an investigated incident into a brief a field team can act on.</p></div><button data-testid="button-print-report" onClick={() => window.print()} disabled={!generated} className="inline-flex items-center gap-2 border border-border bg-card px-3 py-2 text-[11px] font-semibold disabled:opacity-40"><Download size={14} /> Print / save</button></div><div className="grid gap-6 lg:grid-cols-[300px_1fr]"><div className="border border-border bg-card p-5"><div className="font-mono text-[10px] uppercase tracking-[.16em] text-accent">Report builder</div><h2 className="mt-2 text-lg font-bold">Choose an incident</h2><select data-testid="select-report-incident" value={incidentId} onChange={(e) => setIncidentId(e.target.value)} className="mt-5 w-full border border-border bg-background px-3 py-3 text-xs outline-none"><option value="">Select record</option>{(incidents.data ?? []).map((item: any) => <option key={item.id} value={item.id}>{item.locationName} · {item.riskLevel}</option>)}</select><button data-testid="button-generate-report" onClick={createReport} disabled={!incidentId || report.isPending} className="mt-3 flex w-full items-center justify-center gap-2 bg-primary px-4 py-3 text-xs font-bold text-primary-foreground disabled:opacity-45">{report.isPending ? 'Compiling evidence...' : 'Generate incident brief'} <FileText size={14} /></button><p className="mt-4 text-[11px] leading-5 text-muted-foreground">Includes orbital observation, model explanation, risk breakdown, nearby context, and detection history.</p></div><div className="min-h-[480px] border border-border bg-card">{report.error && <QueryState error={report.error} />}{generated ? <div className="p-6 md:p-8" data-testid="generated-report"><div className="flex justify-between gap-4 border-b border-border pb-5"><div><div className="font-mono text-[10px] uppercase tracking-[.18em] text-accent">Thermoscope field brief</div><h1 className="mt-2 text-2xl font-bold tracking-[-.04em]">{generated.title}</h1></div><div className="text-right font-mono text-[9px] text-muted-foreground">{new Date(generated.generatedAt).toLocaleString()}</div></div><IncidentDetail detail={generated.incident} context={generated.incident?.context} history={generated.incident?.history} fire={generated.incident?.observation} /></div> : <EmptyState title="Your brief will appear here" detail="Select an incident and compile the evidence chain." icon={FileText} />}</div></div></div></Shell>;
}

function SystemPage() {
  const status = useGetSystemStatus();
  const health = useHealthCheck();
  const data: any = status.data;
  const rows = data ? [['FIRMS ingest', data.firms], ['OpenStreetMap context', data.osm], ['Classification model', data.classification], ['Persistence engine', data.persistence], ['Risk scoring', data.risk], ['Database', data.database]] : [];
  return <Shell title="System health" eyebrow="Decision support / pipeline"><div className="reveal"><div className="mb-6 flex items-center justify-between"><p className="text-sm text-muted-foreground">Know whether the command picture is live, delayed, or synthetic.</p><button data-testid="button-refresh-system" onClick={() => { status.refetch(); health.refetch(); }} className="inline-flex items-center gap-2 border border-border bg-card px-3 py-2 text-[11px] font-semibold hover:bg-muted"><RefreshCw size={14} /> Refresh checks</button></div><div className="grid gap-3 sm:grid-cols-3"><Metric label="System status" value={health.data?.status ?? (health.isLoading ? '...' : '—')} detail="health endpoint" icon={Activity} accent="accent" /><Metric label="Data mode" value={fmt(data?.dataMode)} detail={`last update ${timeAgo(data?.lastUpdate)}`} icon={Database} /><Metric label="Model version" value={fmt(data?.modelVersion)} detail="classification + risk" icon={Sparkles} accent="accent" /></div><div className="mt-6 grid gap-6 lg:grid-cols-[1.1fr_.7fr]"><div className="border border-border bg-card p-5"><SectionHeading eyebrow="Pipeline checks" title="Signal chain health" /><div className="space-y-1">{status.isLoading ? <LoadingRows count={6} /> : rows.map(([label, value]) => <div key={String(label)} className="flex items-center justify-between border-b border-border py-3 text-xs"><span>{label}</span><span className="flex items-center gap-2 font-mono text-[10px] uppercase"><i className={`h-2 w-2 rounded-full ${String(value).toLowerCase().includes('ok') || String(value).toLowerCase().includes('healthy') || String(value).toLowerCase().includes('online') ? 'bg-accent' : 'bg-primary'}`} />{fmt(value)}</span></div>)}</div></div><div className="border border-sidebar-border bg-sidebar p-5 text-sidebar-foreground"><div className="flex items-center gap-2 text-sidebar-primary"><Radio size={17} /><span className="font-mono text-[10px] uppercase tracking-[.16em]">Operational note</span></div><p className="mt-5 text-sm leading-6 text-sidebar-foreground/75">Data mode is surfaced explicitly so a judging demo can distinguish a live pipeline from scenario data without breaking the investigative workflow.</p><div className="mt-6 border-t border-sidebar-border pt-4 font-mono text-[9px] uppercase tracking-wider text-sidebar-foreground/45">Thermoscope / integrity first</div></div></div></div></Shell>;
}

function Router() {
  return <RoutedErrorBoundary><Switch><Route path="/" component={Dashboard} /><Route path="/map" component={MapPage} /><Route path="/incidents" component={IncidentsPage} /><Route path="/persistent-sources" component={PersistentPage} /><Route path="/alerts" component={AlertsPage} /><Route path="/analytics" component={AnalyticsPage} /><Route path="/copilot" component={CopilotPage} /><Route path="/reports" component={ReportsPage} /><Route path="/system" component={SystemPage} /><Route component={NotFound} /></Switch></RoutedErrorBoundary>;
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;